begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select no_plan();
update private.admin_execution_environment_v1 set environment='DEVELOPMENT'where singleton;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-admin-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then'SUPPORT_AGENT'else'MATRICIA_ADMIN'end from generate_series(1,4)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b1810000-0000-4000-8000-000000000001','Delivery Test','Delivery Test','ACTIVE','a1810000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c1810000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000004','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c1810000-0000-4000-8000-000000000001','CLIENT_OWNER'),('c1810000-0000-4000-8000-000000000001','PROVIDER_OWNER');

update public.platform_user_roles set revoked_at=clock_timestamp()where user_id='a1810000-0000-4000-8000-000000000004';
update public.organization_memberships set status='REVOKED'where user_id='a1810000-0000-4000-8000-000000000004';
insert into public.user_profiles(id,display_name,updated_at)values('a1810000-0000-4000-8000-000000000004','Nom Personnel',now()-interval'40 days')on conflict(id)do update set display_name='Nom Personnel',updated_at=now()-interval'40 days';


insert into public.client_assistance_requests(id,organization_id,created_by,subject,body,status,consented_at,idempotency_key,request_hash,created_at,updated_at)values('f1850000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000004','Assistance privée','Texte personnel à effacer dans la fixture','CLOSED',now()-interval'60 days','fixture-assistance-185',repeat('a',64),now()-interval'60 days',now()-interval'60 days');
insert into public.client_assistance_messages(id,request_id,actor_user_id,body,idempotency_key,created_at)values('f1850000-0000-4000-8000-000000000002','f1850000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001','Réponse personnelle de fixture','fixture-assistance-message185',now()-interval'50 days');
insert into public.processing_activities(id,organization_id,activity_key,name_fr,name_ar,controller_role,systems,countries_regions,cndp_formality_status,created_by)values('f1830000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','profile-retention','Rétention profils','الاحتفاظ بالملفات','CONTROLLER',array['SUPABASE'],array['MA'],'NOT_REQUIRED','a1810000-0000-4000-8000-000000000001');
insert into public.data_categories(id,organization_id,processing_activity_id,category_key,label_fr,label_ar,data_subject_types,sensitivity,created_by)values('f1830000-0000-4000-8000-000000000002','b1810000-0000-4000-8000-000000000001','f1830000-0000-4000-8000-000000000001','user-profile','Profil utilisateur','ملف المستخدم',array['USER'],'PERSONAL','a1810000-0000-4000-8000-000000000001');
insert into public.retention_policies(id,organization_id,data_category_id,version,status,retention_days,trigger_event,disposition,legal_basis_reference,effective_from,created_by)values('f1830000-0000-4000-8000-000000000003','b1810000-0000-4000-8000-000000000001','f1830000-0000-4000-8000-000000000002',1,'ACTIVE',0,'ACCOUNT_REVOKED','ANONYMIZE','fixture-legal-policy-183',current_date-60,'a1810000-0000-4000-8000-000000000001');
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)values('f1830000-0000-4000-8000-000000000004','b1810000-0000-4000-8000-000000000001','ERASURE',encode(extensions.digest(convert_to('b1810000-0000-4000-8000-000000000001:a1810000-0000-4000-8000-000000000004','UTF8'),'sha256'),'hex'),'ENHANCED','fr-MA','IN_REVIEW',now()+interval'1 day',now()-interval'1 day',extensions.gen_random_uuid(),'a1810000-0000-4000-8000-000000000001');

insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)select 'f1910000-0000-4000-8000-000000000001',organization_id,'ACCESS',subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,extensions.gen_random_uuid(),created_by from public.data_subject_requests where id='f1830000-0000-4000-8000-000000000004';
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)select 'f1910000-0000-4000-8000-000000000002',organization_id,'RECTIFICATION',subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,extensions.gen_random_uuid(),created_by from public.data_subject_requests where id='f1830000-0000-4000-8000-000000000004';
create temporary table dsr_results(k text primary key,v jsonb);grant all on dsr_results to authenticated;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a1810000-0000-4000-8000-000000000005','00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-dsr-outsider@example.invalid','',now(),'{}','{}',now(),now());
set local role authenticated;
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.confirm_my_dsr_scope_v1('f1910000-0000-4000-8000-000000000001',array['ALL'],'dsr221-all')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','subject must use MFA before confirming requested scope');
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
insert into dsr_results values('all',public.confirm_my_dsr_scope_v1('f1910000-0000-4000-8000-000000000001',array['ALL'],'dsr221-all'));
select throws_ok($$select public.get_dsr_delivery_console_v1(true,1)$$,'42501','DSR_DELIVERY_CONSOLE_DENIED','subject cannot become staff through a query parameter');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into dsr_results values('partial',public.prepare_admin_dsr_private_response_v1('f1910000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from dsr_results where k='all'),'dsr221-partial'));
select throws_ok($$select public.review_admin_dsr_private_response_v1((select(v->>'response_id')::uuid from dsr_results where k='partial'),(select v->>'sha256'from dsr_results where k='partial'),true,true,'Independent review is required')$$,'42501','DSR_INDEPENDENT_REVIEW_REQUIRED','response preparer cannot publish their own response');
reset role;
select is((select(v->>'complete')::boolean from dsr_results where k='partial'),false,'ALL remains explicitly partial when only subset assemblers exist');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into dsr_results values('partial-approved',public.review_admin_dsr_private_response_v1((select(v->>'response_id')::uuid from dsr_results where k='partial'),(select v->>'sha256'from dsr_results where k='partial'),true,true,'Partial disclosure reviewed; remaining scope requires assembly'));
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select public.get_private_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='partial'));
select public.acknowledge_my_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='partial'),(select(v->>'scope_version_id')::uuid from dsr_results where k='all'),(select v->>'sha256'from dsr_results where k='partial'));
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.transition_data_subject_request('f1910000-0000-4000-8000-000000000001',1,'FULFILLED','PARTIAL_ACK',(select 'privacy-response:'||(v->>'response_id')from dsr_results where k='partial'),extensions.gen_random_uuid())$$,'55000','PRIVACY_SCOPE_REVIEW_AND_SUBJECT_DELIVERY_REQUIRED','acknowledged partial ALL response still cannot fulfil request');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
insert into dsr_results values('scope2',public.confirm_my_dsr_scope_v1('f1910000-0000-4000-8000-000000000001',array['OWN_MESSAGES','ACCOUNT'],'dsr221-scope2'));
select throws_ok($$select public.acknowledge_my_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='partial'),(select(v->>'scope_version_id')::uuid from dsr_results where k='all'),(select v->>'sha256'from dsr_results where k='partial'))$$,'40001','STALE_DSR_RESPONSE','new requested scope invalidates the previous acknowledgement pathway');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into dsr_results values('complete',public.prepare_admin_dsr_private_response_v1('f1910000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from dsr_results where k='scope2'),'dsr221-complete'));
insert into dsr_results values('complete-replay',public.prepare_admin_dsr_private_response_v1('f1910000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from dsr_results where k='scope2'),'dsr221-complete'));
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.get_private_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'))$$,'42501','DSR_PRIVATE_RESPONSE_DENIED','subject cannot access a response before independent review');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.review_admin_dsr_private_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),repeat('0',64),true,true,'Scope and privacy reviewed')$$,'40001','STALE_DSR_RESPONSE','review must bind exact artifact hash');
select throws_ok($$select public.review_admin_dsr_private_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),(select v->>'sha256'from dsr_results where k='complete'),true,false,'Scope and privacy reviewed')$$,'22023','DSR_SCOPE_AND_THIRD_PARTY_REVIEW_REQUIRED','approval requires explicit scope and third-party privacy review');
insert into dsr_results values('complete-approved',public.review_admin_dsr_private_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),(select v->>'sha256'from dsr_results where k='complete'),true,true,'Scope and absence of restricted third-party data reviewed'));
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000005',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.get_private_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'))$$,'42501','DSR_PRIVATE_RESPONSE_DENIED','another account cannot download the published private response');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.acknowledge_my_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),(select(v->>'scope_version_id')::uuid from dsr_results where k='scope2'),(select v->>'sha256'from dsr_results where k='complete'))$$,'55000','DSR_APPROVED_RESPONSE_ACCESS_REQUIRED','acknowledgement requires a preceding private access grant');
insert into dsr_results values('download',public.get_private_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete')));
select throws_ok($$select public.acknowledge_my_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),(select(v->>'scope_version_id')::uuid from dsr_results where k='scope2'),repeat('0',64))$$,'40001','STALE_DSR_RESPONSE','receipt binds the exact downloaded artifact hash');
select public.acknowledge_my_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),(select(v->>'scope_version_id')::uuid from dsr_results where k='scope2'),(select v->>'sha256'from dsr_results where k='complete'));
select public.acknowledge_my_dsr_response_v1((select(v->>'response_id')::uuid from dsr_results where k='complete'),(select(v->>'scope_version_id')::uuid from dsr_results where k='scope2'),(select v->>'sha256'from dsr_results where k='complete'));
reset role;
select is((select v from dsr_results where k='complete'),(select v from dsr_results where k='complete-replay'),'prepare replay returns the same private artifact and hash');
select is((select encode(extensions.digest(convert_to(v->>'response_json','UTF8'),'sha256'),'hex')from dsr_results where k='download'),(select v->>'sha256'from dsr_results where k='complete'),'download hash binds exact UTF-8 artifact bytes');
select ok((select(v->>'response_json')::jsonb?'account'and(v->>'response_json')::jsonb?'own_messages'and not((v->>'response_json')::jsonb?'assistance')and v->>'response_json'not like'%encrypted_password%'from dsr_results where k='download'),'response contains precisely confirmed supported scopes and no authentication secrets');
select is((select status from public.organization_memberships where id='c1810000-0000-4000-8000-000000000001'),'REVOKED','private delivery works independently of current organization membership');
select is((select count(*)from public.dsr_private_response_ack_v1 where response_id=(select(v->>'response_id')::uuid from dsr_results where k='complete')),1::bigint,'receipt replay persists exactly one immutable acknowledgement');
select is((select status from public.data_subject_requests where id='f1910000-0000-4000-8000-000000000001'),'IN_REVIEW','subject acknowledgement does not automatically fulfil a request');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.transition_data_subject_request('f1910000-0000-4000-8000-000000000001',1,'FULFILLED','SCOPE_DELIVERED_ACK',(select 'privacy-response:'||(v->>'response_id')from dsr_results where k='complete'),extensions.gen_random_uuid())$$,'staff can fulfil only independently reviewed complete acknowledged response');
reset role;
select is((select status from public.data_subject_requests where id='f1910000-0000-4000-8000-000000000001'),'FULFILLED','complete requested scope and receipt enable controlled fulfilment');
select*from finish();rollback;
